function openIMSettings(){setModule('业务概览');document.querySelector('main').hidden=true;document.querySelectorAll('.main>.market-view,.main>.activity-view,.main>.task-view').forEach(v=>v.hidden=true);let view=document.getElementById('settings-view');if(!view){view=document.createElement('section');view.id='settings-view';view.className='market-view';view.innerHTML='<iframe title="个人设置" src="settings.html"></iframe>';document.querySelector('.main').append(view)}view.hidden=false;document.getElementById('crumb').textContent='设置';document.querySelectorAll('#workspace-sidebar .nav').forEach(b=>b.classList.remove('active'));document.getElementById('settings-nav').classList.add('active');window.scrollTo(0,0)}
document.getElementById('workspace-sidebar').addEventListener('click',e=>{if(e.target.closest('#settings-nav'))return;if(e.target.closest('.nav,[data-session]')){document.getElementById('settings-view')?.setAttribute('hidden','');document.getElementById('settings-nav').classList.remove('active')}},true);
